use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::{FieldSchema, FieldType, PluginSchema};
use parking_lot::Mutex;
use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::collections::{HashMap, HashSet};
use std::os::unix::net::UnixListener;
use std::path::Path;
use std::sync::Arc;
use tracing::{info, warn};

/// The single active-schema catalog in shared memory. Every plugin reads its
/// own slice by name from this one file — there is no per-plugin shm file and
/// no diff loop. The schema's declared state IS the desired state.
const SHM_SCHEMA_PATH: &str = "/dev/shm/live-schema.json";

fn default_protocol() -> String {
    "grpc".to_string()
}

/// A configured unix-domain socket endpoint.
///
/// In the single-socket model, one shared socket (e.g.
/// `/run/ghostbridge/container.sock`) serves all services.  xray routes by
/// domain/SNI to the tonic-web gRPC bridge, which listens on this socket and
/// demuxes by gRPC service/method (via reflection).
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct SocketEndpoint {
    /// Container/service identity (the `createunixsocket --name`). The tonic-web
    /// gRPC bridge demuxes by gRPC service/method via server reflection — this
    /// name is the routing/identity tag gemma emits into the xray config; it is
    /// NOT a network namespace (filesystem UDS are not netns-scoped).
    #[serde(default)]
    #[schemars(
        description = "Container/service identity tag the bridge routes by (createunixsocket --name)",
        example = &"netmaker",
        extend("x-oscal-subid" = "mut.service.unix-socket.bind-name@v1")
    )]
    pub name: String,
    /// Filesystem path to the shared socket.
    #[schemars(
        description = "Filesystem path of the shared unix domain socket",
        example = &"/run/ghostbridge/container.sock",
        extend("x-oscal-subid" = "mut.service.unix-socket.bind-path@v1")
    )]
    pub path: String,
    /// Backend TCP ports this container serves (the `createunixsocket --port`
    /// list, e.g. `25,465,587` for mail). Recorded metadata only — tonic-web
    /// distinguishes single vs multi protocol and demuxes by reflection, so the
    /// plugin neither opens these ports nor maps them; they describe the backend.
    #[serde(default)]
    #[schemars(
        description = "Backend TCP ports the container serves (metadata; tonic-web demuxes by reflection)",
        example = &[25u16, 465, 587],
        extend("x-oscal-subid" = "mut.service.unix-socket.bind-port@v1")
    )]
    pub ports: Vec<u16>,
    /// Transport protocol carried over the socket.
    #[serde(default = "default_protocol")]
    #[schemars(
        description = "Transport protocol carried over the socket (grpc, jsonrpc, …)",
        extend("x-oscal-subid" = "mut.service.unix-socket.bind-protocol@v1")
    )]
    pub protocol: String,
    /// Human-readable label for the shared socket.
    #[serde(default)]
    #[schemars(
        description = "Human-readable label for the shared socket",
        example = &"ghostbridge",
        extend("x-oscal-subid" = "mut.service.unix-socket.bind-label@v1")
    )]
    pub label: String,
}

/// Canonical path for the single shared bidirectional socket every container
/// uses to reach the tonic-web gRPC bridge.
pub const SHARED_CONTAINER_SOCKET: &str = "/run/ghostbridge/container.sock";

/// Runtime state: the single shared socket endpoint for the gRPC bridge.
#[derive(Debug, Clone, Serialize, Deserialize, Default, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.plugin.unix-socket.schema@v1"))]
pub struct UnixSocketState {
    /// The shared socket endpoint (one socket, all services route through it).
    #[schemars(
        description = "The shared socket endpoint (one socket, all services route through it by domain)",
        extend("x-oscal-subid" = "mut.service.unix-socket.bind@v1")
    )]
    pub sockets: Vec<SocketEndpoint>,
}

/// Canonical `unix_socket` schema, **derived** from the structs via schemars
/// (see [`super::schemars_adapter`]). `port` bounds, field descriptions (from
/// doc comments) and `required` flags all come from the type — the struct is
/// the single source of truth. The frozen hand-rolled `unix_socket_schema()`
/// (test-only) guards this against drift via `derived_schema_matches_hand_rolled`.
pub fn unix_socket_schema_derived() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(UnixSocketState))
        .expect("schemars schema serializes to JSON");
    super::schemars_adapter::plugin_schema_from_json(
        "unix_socket",
        "1.0.0",
        "Single shared unix-domain socket for the tonic-web gRPC bridge — all services route through it, demuxed by domain/SNI at xray and by gRPC service/method at the bridge",
        &root,
    )
}

pub struct UnixSocketPlugin {
    /// Live listeners keyed by socket path. Holding the `UnixListener` keeps the
    /// socket bound for the lifetime of the plugin; dropping it tears it down.
    active: Arc<Mutex<HashMap<String, UnixListener>>>,
}

impl UnixSocketPlugin {
    pub fn new() -> Self {
        Self {
            active: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    /// Read this plugin's desired socket set straight from the single active
    /// schema catalog in shared memory (zero-copy 1:1). The catalog is keyed by
    /// plugin name and each entry carries the schema-declared state.
    fn read_desired() -> UnixSocketState {
        let Ok(mut bytes) = std::fs::read(SHM_SCHEMA_PATH) else {
            return UnixSocketState::default();
        };
        let Ok(catalog) = simd_json::to_owned_value(&mut bytes) else {
            return UnixSocketState::default();
        };
        let Some(state) = catalog
            .get("unix_socket")
            .and_then(|versions| versions.as_array())
            .and_then(|versions| versions.last())
            .and_then(|schema| schema.get("example"))
        else {
            return UnixSocketState::default();
        };
        simd_json::serde::from_owned_value::<UnixSocketState>(state.clone()).unwrap_or_default()
    }

    /// Bind a single endpoint, replacing any stale socket file. Returns `true`
    /// when a new listener was created.
    fn ensure_bound(
        active: &mut HashMap<String, UnixListener>,
        endpoint: &SocketEndpoint,
    ) -> Result<bool> {
        if active.contains_key(&endpoint.path) {
            return Ok(false);
        }
        if let Some(parent) = Path::new(&endpoint.path).parent() {
            std::fs::create_dir_all(parent)?;
        }
        if Path::new(&endpoint.path).exists() {
            std::fs::remove_file(&endpoint.path)?;
        }
        let listener = UnixListener::bind(&endpoint.path)?;
        listener.set_nonblocking(true)?;
        active.insert(endpoint.path.clone(), listener);
        info!(
            socket = %endpoint.path,
            name = %endpoint.name,
            ports = ?endpoint.ports,
            protocol = %endpoint.protocol,
            "bound unix socket endpoint"
        );
        Ok(true)
    }

    /// Drop a listener and unlink its socket file. Returns `true` when removed.
    fn unbind(active: &mut HashMap<String, UnixListener>, path: &str) -> bool {
        if active.remove(path).is_some() {
            if let Err(error) = std::fs::remove_file(path) {
                warn!(socket = %path, %error, "failed to unlink unix socket file");
            }
            true
        } else {
            false
        }
    }

    /// Reconcile the live listeners to exactly the supplied desired set.
    fn reconcile(&self, desired: &UnixSocketState) -> ApplyResult {
        let mut active = self.active.lock();
        let mut changes_applied = Vec::new();
        let mut errors = Vec::new();

        let wanted: HashSet<String> = desired.sockets.iter().map(|s| s.path.clone()).collect();

        for endpoint in &desired.sockets {
            match Self::ensure_bound(&mut active, endpoint) {
                Ok(true) => changes_applied.push(format!(
                    "created socket {} (name {}, ports {:?}, {})",
                    endpoint.path, endpoint.name, endpoint.ports, endpoint.protocol
                )),
                Ok(false) => {}
                Err(error) => errors.push(format!(
                    "failed to create socket {}: {}",
                    endpoint.path, error
                )),
            }
        }

        let stale: Vec<String> = active
            .keys()
            .filter(|path| !wanted.contains(*path))
            .cloned()
            .collect();
        for path in stale {
            if Self::unbind(&mut active, &path) {
                changes_applied.push(format!("removed socket {}", path));
            }
        }

        ApplyResult {
            success: errors.is_empty(),
            changes_applied,
            errors,
            checkpoint: None,
        }
    }

    /// `createunixsocket --name <name> --port <csv>` — register a container/service
    /// against the single shared `container.sock`.
    ///
    /// Pure transport, no OVS: the shared socket is bound once; `name` is the
    /// identity/demux tag (gemma emits it into the xray config) and `ports` are
    /// recorded backend metadata only. tonic-web distinguishes single vs multi
    /// protocol and demuxes by gRPC server reflection, so the plugin neither
    /// opens these ports nor maps them — OSCAL rule-enforcement routing lives in
    /// the separate OpenFlow/policy layer, not in the socket.
    pub fn create_unix_socket(&self, name: impl Into<String>, ports: Vec<u16>) -> ApplyResult {
        let endpoint = SocketEndpoint {
            name: name.into(),
            path: SHARED_CONTAINER_SOCKET.to_string(),
            ports,
            protocol: default_protocol(),
            label: String::new(),
        };
        let mut active = self.active.lock();
        match Self::ensure_bound(&mut active, &endpoint) {
            Ok(_) => ApplyResult {
                success: true,
                changes_applied: vec![format!(
                    "registered '{}' on shared socket {} (ports {:?})",
                    endpoint.name, endpoint.path, endpoint.ports
                )],
                errors: vec![],
                checkpoint: None,
            },
            Err(error) => ApplyResult {
                success: false,
                changes_applied: vec![],
                errors: vec![format!(
                    "createunixsocket '{}' failed: {}",
                    endpoint.name, error
                )],
                checkpoint: None,
            },
        }
    }
}

impl Default for UnixSocketPlugin {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl StatePlugin for UnixSocketPlugin {
    fn name(&self) -> &str {
        "unix_socket"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<op_state_store::PluginSchema> {
        let mut schema = unix_socket_schema_derived();
        super::common::oscal::ensure_category_metadata_fields(&mut schema);
        Some(schema)
    }

    async fn query_current_state(&self) -> Result<Value> {
        // The schema-declared desired state in the active-schema catalog is the
        // current state (1:1, zero-copy). Fall back to whatever is live-bound.
        let mut state = Self::read_desired();
        if state.sockets.is_empty() {
            let active = self.active.lock();
            state.sockets = active
                .keys()
                .map(|path| SocketEndpoint {
                    name: String::new(),
                    path: path.clone(),
                    ports: Vec::new(),
                    protocol: default_protocol(),
                    label: String::new(),
                })
                .collect();
        }
        Ok(simd_json::serde::to_owned_value(state)?)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        // No diff loop: the schema-declared state is authoritative and applied
        // wholesale by `apply_state`.
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "schema".to_string(),
                desired_hash: "schema".to_string(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        // Reconcile the live unix sockets to exactly the schema-declared set.
        let desired = Self::read_desired();
        Ok(self.reconcile(&desired))
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        let desired = Self::read_desired();
        let active = self.active.lock();
        let satisfied = desired.sockets.iter().all(|endpoint| {
            active.contains_key(&endpoint.path) && Path::new(&endpoint.path).exists()
        });
        Ok(satisfied)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::read_desired())?,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
        let snapshot = simd_json::serde::from_owned_value::<UnixSocketState>(
            checkpoint.state_snapshot.clone(),
        )
        .unwrap_or_default();
        self.reconcile(&snapshot);
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: true,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn endpoint(dir: &std::path::Path, name: &str, port: u16) -> SocketEndpoint {
        SocketEndpoint {
            name: name.to_string(),
            path: dir.join(name).to_string_lossy().into_owned(),
            ports: vec![port],
            protocol: "grpc".to_string(),
            label: name.to_string(),
        }
    }

    fn sockets_object(s: &PluginSchema) -> &HashMap<String, FieldSchema> {
        match &s.fields.get("sockets").expect("sockets field").field_type {
            FieldType::Array(inner) => match inner.as_ref() {
                FieldType::Object(m) => m,
                other => panic!("items not object: {other:?}"),
            },
            other => panic!("sockets not array: {other:?}"),
        }
    }

    /// The schemars-derived schema must match the hand-rolled one field-for-field.
    #[test]
    fn derived_schema_matches_hand_rolled() {
        let hand = unix_socket_schema();
        let derived = unix_socket_schema_derived();

        assert_eq!(derived.name, hand.name);
        assert_eq!(derived.version, hand.version);

        let hp = sockets_object(&hand);
        let dp = sockets_object(&derived);

        let mut hk: Vec<_> = hp.keys().cloned().collect();
        let mut dk: Vec<_> = dp.keys().cloned().collect();
        hk.sort();
        dk.sort();
        assert_eq!(dk, hk, "derived inner fields must match hand-rolled");

        // ports: Array (derived from `Vec<u16>`)
        assert!(matches!(dp["ports"].field_type, FieldType::Array(_)));

        // doc comments survive as descriptions
        assert!(!dp["path"].description.is_empty());
        // required set: path only (name/ports/protocol/label have serde defaults)
        assert!(dp["path"].required);
        assert!(
            !dp["name"].required
                && !dp["ports"].required
                && !dp["protocol"].required
                && !dp["label"].required
        );

        // OSCAL subids are preserved at the schema and field level.
        assert_eq!(
            derived.subids.get("__schema__"),
            Some(&"sch.software.plugin.unix-socket.schema@v1".to_string())
        );
        assert_eq!(
            derived.subids.get("sockets"),
            Some(&"mut.service.unix-socket.bind@v1".to_string())
        );
    }

    #[test]
    fn schema_carries_oscal_subids() {
        let raw = serde_json::to_value(schemars::schema_for!(UnixSocketState)).unwrap();
        assert_eq!(
            raw.get("x-oscal-subid").and_then(|v| v.as_str()),
            Some("sch.software.plugin.unix-socket.schema@v1")
        );

        let sockets = raw
            .get("properties")
            .and_then(|p| p.get("sockets"))
            .expect("sockets property");
        assert_eq!(
            sockets.get("x-oscal-subid").and_then(|v| v.as_str()),
            Some("mut.service.unix-socket.bind@v1")
        );

        let endpoint_def = raw
            .get("$defs")
            .or_else(|| raw.get("definitions"))
            .and_then(|d| d.get("SocketEndpoint"))
            .expect("SocketEndpoint $def");
        let props = endpoint_def
            .get("properties")
            .expect("SocketEndpoint properties");

        let expected = [
            ("name", "mut.service.unix-socket.bind-name@v1"),
            ("path", "mut.service.unix-socket.bind-path@v1"),
            ("ports", "mut.service.unix-socket.bind-port@v1"),
            ("protocol", "mut.service.unix-socket.bind-protocol@v1"),
            ("label", "mut.service.unix-socket.bind-label@v1"),
        ];
        for (field, subid) in expected {
            let actual = props
                .get(field)
                .and_then(|f| f.get("x-oscal-subid"))
                .and_then(|v| v.as_str());
            assert_eq!(actual, Some(subid), "subid mismatch for {field}");
        }
    }

    #[test]
    fn should_bind_and_unbind_declared_sockets() {
        let dir = tempfile::tempdir().expect("tempdir");
        let plugin = UnixSocketPlugin::new();

        let ep = endpoint(dir.path(), "qdrant.sock", 6334);
        let desired = UnixSocketState {
            sockets: vec![ep.clone()],
        };

        let result = plugin.reconcile(&desired);
        assert!(result.success, "errors: {:?}", result.errors);
        assert!(std::path::Path::new(&ep.path).exists());
        assert!(plugin.active.lock().contains_key(&ep.path));

        // Reconciling to an empty set tears the socket down.
        let cleared = plugin.reconcile(&UnixSocketState::default());
        assert!(cleared.success);
        assert!(!std::path::Path::new(&ep.path).exists());
        assert!(plugin.active.lock().is_empty());
    }

    #[test]
    fn should_be_idempotent_for_already_bound_sockets() {
        let dir = tempfile::tempdir().expect("tempdir");
        let plugin = UnixSocketPlugin::new();
        let desired = UnixSocketState {
            sockets: vec![
                endpoint(dir.path(), "a.sock", 1),
                endpoint(dir.path(), "b.sock", 2),
            ],
        };

        let first = plugin.reconcile(&desired);
        assert_eq!(first.changes_applied.len(), 2);

        // Second reconcile against the same desired set creates nothing new.
        let second = plugin.reconcile(&desired);
        assert!(second.changes_applied.is_empty());
        assert_eq!(plugin.active.lock().len(), 2);
    }
}

/// Frozen golden reference: the original hand-rolled schema, kept **test-only**
/// so `derived_schema_matches_hand_rolled` can prove the derived schema still
/// matches the contract this plugin shipped with. Production uses
/// [`unix_socket_schema_derived`].
#[cfg(test)]
pub(crate) fn unix_socket_schema() -> PluginSchema {
    let mut socket_fields = HashMap::new();
    socket_fields.insert(
        "name".to_string(),
        FieldSchema {
            field_type: FieldType::String,
            required: false,
            description:
                "Container/service identity tag the bridge routes by (createunixsocket --name)"
                    .to_string(),
            default: Some(json!("")),
            example: Some(json!("netmaker")),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    socket_fields.insert(
        "path".to_string(),
        FieldSchema {
            field_type: FieldType::String,
            required: true,
            description: "Filesystem path of the shared unix domain socket".to_string(),
            default: None,
            example: Some(json!("/run/ghostbridge/container.sock")),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    socket_fields.insert(
        "ports".to_string(),
        FieldSchema {
            field_type: FieldType::Array(Box::new(FieldType::Integer)),
            required: false,
            description:
                "Backend TCP ports the container serves (metadata; tonic-web demuxes by reflection)"
                    .to_string(),
            default: Some(json!([])),
            example: Some(json!([25, 465, 587])),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    socket_fields.insert(
        "protocol".to_string(),
        FieldSchema {
            field_type: FieldType::String,
            required: false,
            description: "Transport protocol carried over the socket (grpc, jsonrpc, …)"
                .to_string(),
            default: Some(json!("grpc")),
            example: None,
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    socket_fields.insert(
        "label".to_string(),
        FieldSchema {
            field_type: FieldType::String,
            required: false,
            description: "Human-readable label for the shared socket".to_string(),
            default: Some(json!("")),
            example: Some(json!("ghostbridge")),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );

    PluginSchema::builder("unix_socket")
        .version("1.0.0")
        .description("Single shared unix-domain socket for the tonic-web gRPC bridge — all services route through it, demuxed by domain/SNI at xray and by gRPC service/method at the bridge")
        .subid("__schema__", "sch.software.plugin.unix-socket.schema@v1")
        .array_field(
            "sockets",
            FieldType::Object(socket_fields),
            true,
            "The shared socket endpoint (one socket, all services route through it by domain)",
        )
        .subid("sockets", "mut.service.unix-socket.bind@v1")
        .example(json!({
            "sockets": [
                {
                    "name": "netmaker",
                    "path": "/run/ghostbridge/container.sock",
                    "ports": [18081, 1883, 8883],
                    "protocol": "grpc",
                    "label": "ghostbridge"
                }
            ]
        }))
        .build()
}

//! Incus state plugin - manages Incus containers and virtual machines.
//!
//! Uses the `incus` CLI with `--format=json` for all operations.
//! Supports creating, starting, stopping, and deleting instances,
//! as well as profile and config management.

use anyhow::{Context, Result};
use async_trait::async_trait;
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use op_state_store::{FieldSchema, FieldType, PluginSchema};
use serde::{Deserialize, Serialize};
use simd_json::{json, prelude::*, OwnedValue as Value};
use std::collections::HashMap;
use std::time::Duration;
use tokio::io::{AsyncReadExt, AsyncWriteExt};

/// Top-level state representing all Incus instances on the system.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IncusState {
    pub instances: Vec<IncusInstance>,
}

/// A proxy device exposed as a Unix socket on the host.
/// The `id` field is the Incus device name — used as the D-Bus object path segment.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct IncusProxySocket {
    /// Incus device name (e.g. "grpc-socket", "mail-imap") — D-Bus path segment.
    pub id: String,
    /// Host-side listen address (e.g. "unix:/run/assistant.sock")
    pub listen: String,
    /// Container-side connect address (e.g. "tcp:127.0.0.1:50051")
    pub connect: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bind: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub uid: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub gid: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mode: Option<String>,
}

/// A single Incus instance (container or virtual-machine).
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct IncusInstance {
    pub name: String,
    /// Instance status: "Running", "Stopped", "Frozen"
    pub status: String,
    /// Instance type: "container" or "virtual-machine"
    #[serde(rename = "type")]
    pub instance_type: String,
    /// Image description (extracted from config)
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub image: Option<String>,
    /// Preferred storage pool used during initial creation.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub storage_pool: Option<String>,
    /// Applied profiles (e.g. ["default"])
    #[serde(default)]
    pub profiles: Vec<String>,
    /// Human-readable description
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    /// CPU architecture (e.g. "x86_64")
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub architecture: Option<String>,
    /// Delete instance on shutdown
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub ephemeral: Option<bool>,
    /// Whether saved state exists on disk
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub stateful: Option<bool>,
    /// Creation timestamp (ISO8601)
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub created_at: Option<String>,
    /// Last start timestamp (ISO8601)
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_used_at: Option<String>,
    /// Cluster member location ("none" on single-node)
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub location: Option<String>,
    /// Incus project name
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub project: Option<String>,
    /// Instance configuration key-value pairs
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub config: Option<HashMap<String, String>>,
    /// Non-proxy device definitions (NICs, disks, etc.)
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub devices: Option<HashMap<String, HashMap<String, String>>>,
    /// Proxy devices exposed as Unix sockets on the host.
    /// Each entry has an `id` field (the device name) for named D-Bus paths.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub sockets: Vec<IncusProxySocket>,
}

/// Intermediate struct for deserializing raw `incus list --format=json` output.
#[derive(Debug, Deserialize)]
struct RawIncusInstance {
    name: String,
    status: String,
    #[serde(rename = "type")]
    instance_type: String,
    #[serde(default)]
    profiles: Vec<String>,
    #[serde(default)]
    config: HashMap<String, String>,
    #[serde(default)]
    devices: HashMap<String, HashMap<String, String>>,
    #[serde(default)]
    description: String,
    #[serde(default)]
    architecture: String,
    #[serde(default)]
    ephemeral: bool,
    #[serde(default)]
    stateful: bool,
    #[serde(default)]
    created_at: String,
    #[serde(default)]
    last_used_at: String,
    #[serde(default)]
    location: String,
    #[serde(default)]
    project: String,
}

/// Derive a human-readable socket id from a connect address.
/// "tcp:127.0.0.1:50051" → "grpc", "tcp:127.0.0.1:143" → "imap", etc.
/// Falls back to the port number string, then None if unparseable.
fn socket_id_from_connect(connect: &str) -> Option<String> {
    let port_str = connect.rsplit(':').next()?;
    let port: u16 = port_str.trim().parse().ok()?;
    let name = match port {
        21 => "ftp",
        22 => "ssh",
        25 => "smtp",
        53 => "dns",
        80 => "http",
        110 => "pop3",
        143 => "imap",
        443 => "https",
        465 => "smtps",
        587 => "submission",
        993 => "imaps",
        995 => "pop3s",
        1883 => "mqtt",
        3306 => "mysql",
        5432 => "postgres",
        5672 => "amqp",
        6333 => "qdrant-http",
        6334 => "qdrant-grpc",
        8080 | 8081 | 8443 => "http-alt",
        8883 => "mqtt-tls",
        18789 => "ghostbridge",
        50051 => "grpc",
        50052 => "grpc-mcp",
        50053 => "grpc-services",
        _ => return Some(port_str.to_string()),
    };
    Some(name.to_string())
}

pub struct IncusPlugin;

impl IncusPlugin {
    pub fn new() -> Self {
        Self
    }

    /// Minimal HTTP-over-UnixSocket client for Incus REST API (AGENTS.md §4: no subprocess bypasses)
    async fn incus_api_request(method: &str, path: &str, body: Option<&str>) -> Result<Vec<u8>> {
        let socket_path = "/var/lib/incus/unix.socket";
        if !std::path::Path::new(socket_path).exists() {
            return Err(anyhow::anyhow!(
                "Incus Unix socket not found at {}",
                socket_path
            ));
        }

        let mut stream = tokio::net::UnixStream::connect(socket_path)
            .await
            .context("Failed to connect to Incus Unix socket")?;

        let body_len = body.map(|b| b.len()).unwrap_or(0);
        let request = format!(
            "{} {} HTTP/1.1\r\nHost: localhost\r\nAccept: application/json\r\n{}Content-Length: {}\r\n\r\n{}",
            method,
            path,
            if body.is_some() {
                "Content-Type: application/json\r\n"
            } else {
                ""
            },
            body_len,
            body.unwrap_or("")
        );

        stream.write_all(request.as_bytes()).await?;

        let mut response = Vec::new();
        let mut buf = [0u8; 4096];
        loop {
            match tokio::time::timeout(Duration::from_millis(500), stream.read(&mut buf)).await {
                Ok(Ok(0)) => break,
                Ok(Ok(n)) => response.extend_from_slice(&buf[..n]),
                Ok(Err(e)) => return Err(e.into()),
                Err(_) => break, // timeout: assume response is complete
            }
        }

        // Extract body from HTTP response
        let body_start = if let Some(idx) = response.windows(4).position(|w| w == b"\r\n\r\n") {
            idx + 4
        } else if let Some(idx) = response.windows(2).position(|w| w == b"\n\n") {
            idx + 2
        } else {
            return Ok(response);
        };

        let headers = std::str::from_utf8(&response[..body_start]).unwrap_or("");
        let mut body = response[body_start..].to_vec();

        // Handle chunked transfer encoding
        if headers
            .to_lowercase()
            .contains("transfer-encoding: chunked")
        {
            let mut decoded = Vec::new();
            let mut pos = 0;
            while pos < body.len() {
                let mut line_end = pos;
                while line_end < body.len() && body[line_end] != b'\n' {
                    line_end += 1;
                }
                if line_end >= body.len() {
                    break;
                }
                let line = std::str::from_utf8(&body[pos..line_end])
                    .unwrap_or("")
                    .trim();
                let size = usize::from_str_radix(line.split(';').next().unwrap_or("0").trim(), 16)
                    .unwrap_or(0);
                if size == 0 {
                    break;
                }
                pos = line_end + 1;
                if pos < body.len() && body[pos] == b'\r' {
                    pos += 1;
                }
                decoded.extend_from_slice(&body[pos..pos + size]);
                pos += size;
                if pos < body.len() && body[pos] == b'\r' {
                    pos += 1;
                }
                if pos < body.len() && body[pos] == b'\n' {
                    pos += 1;
                }
            }
            body = decoded;
        }

        Ok(body)
    }

    /// Call Incus REST API and extract metadata from sync response
    async fn incus_api_call(method: &str, path: &str, body: Option<&str>) -> Result<Vec<u8>> {
        let response = Self::incus_api_request(method, path, body).await?;
        let mut raw = response;
        let val: simd_json::OwnedValue =
            simd_json::from_slice(&mut raw).context("Failed to parse Incus API response")?;

        let status = val
            .get("status")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_lowercase();
        if status == "success" || status == "created" || status == "accepted" {
            let metadata = val.get("metadata").cloned().unwrap_or(simd_json::json!({}));
            Ok(simd_json::to_string(&metadata)?.into_bytes())
        } else {
            let err = val
                .get("error")
                .and_then(|v| v.as_str())
                .or_else(|| val.get("status").and_then(|v| v.as_str()))
                .unwrap_or("Unknown Incus API error");
            Err(anyhow::anyhow!("Incus API error: {}", err))
        }
    }

    /// Fetch current instance configuration via REST API
    async fn incus_get_instance(name: &str) -> Result<simd_json::OwnedValue> {
        let body =
            Self::incus_api_call("GET", &format!("/1.0/instances/{}?recursion=1", name), None)
                .await?;
        let mut raw = body;
        simd_json::from_slice(&mut raw).context("Failed to parse Incus instance")
    }

    /// Update instance configuration via REST API (removes read-only fields first)
    async fn incus_update_instance(name: &str, mut config: simd_json::OwnedValue) -> Result<()> {
        if let Some(obj) = config.as_object_mut() {
            obj.retain(|k, _| !k.starts_with("volatile.") && !k.starts_with("image."));
        }
        let body = simd_json::to_string(&config)?;
        Self::incus_api_call("PUT", &format!("/1.0/instances/{}", name), Some(&body)).await?;
        Ok(())
    }

    /// Run an incus operation via REST API (AGENTS.md §4: no subprocess bypasses)
    async fn run_incus_command(args: &[&str]) -> Result<Vec<u8>> {
        match args {
            ["list", "--format=json"] => {
                Self::incus_api_call("GET", "/1.0/instances?recursion=1", None).await
            }
            ["init", ..] => {
                let mut image = "";
                let mut name = "";
                let mut storage_pool = None;
                let mut profiles: Vec<String> = Vec::new();
                let mut no_profiles = false;
                let mut i = 1;
                while i < args.len() {
                    match args[i] {
                        "--storage" => {
                            i += 1;
                            storage_pool = args.get(i).copied().map(String::from);
                        }
                        "--no-profiles" => {
                            no_profiles = true;
                        }
                        "--profile" => {
                            i += 1;
                            if let Some(p) = args.get(i) {
                                profiles.push(p.to_string());
                            }
                        }
                        arg if arg.starts_with('-') => {}
                        arg if image.is_empty() => image = arg,
                        arg if name.is_empty() => name = arg,
                        _ => {}
                    }
                    i += 1;
                }

                let mut body = simd_json::json!({
                    "name": name,
                    "source": { "type": "image", "alias": image },
                    "type": "container",
                });
                if no_profiles {
                    body["profiles"] = simd_json::json!([]);
                } else if !profiles.is_empty() {
                    body["profiles"] = simd_json::json!(profiles);
                }
                if let Some(pool) = storage_pool {
                    body["devices"] = simd_json::json!({
                        "root": {
                            "type": "disk",
                            "pool": pool,
                            "path": "/"
                        }
                    });
                }
                let body_str = simd_json::to_string(&body)?;
                Self::incus_api_call("POST", "/1.0/instances", Some(&body_str)).await
            }
            ["delete", name, "--force"] => {
                Self::incus_api_call("DELETE", &format!("/1.0/instances/{}?force=1", name), None)
                    .await
            }
            ["start", name] => {
                let body = r#"{"action":"start"}"#;
                Self::incus_api_call("PUT", &format!("/1.0/instances/{}/state", name), Some(body))
                    .await
            }
            ["stop", name] => {
                let body = r#"{"action":"stop"}"#;
                Self::incus_api_call("PUT", &format!("/1.0/instances/{}/state", name), Some(body))
                    .await
            }
            ["pause", name] => {
                let body = r#"{"action":"freeze"}"#;
                Self::incus_api_call("PUT", &format!("/1.0/instances/{}/state", name), Some(body))
                    .await
            }
            ["profile", "remove", name, profile] => {
                let mut data = Self::incus_get_instance(name).await?;
                if let Some(profiles_arr) = data.get_mut("profiles").and_then(|p| p.as_array_mut())
                {
                    profiles_arr.retain(|p| p.as_str() != Some(profile));
                }
                Self::incus_update_instance(name, data).await?;
                Ok(Vec::new())
            }
            ["profile", "add", name, profile] => {
                let mut data = Self::incus_get_instance(name).await?;
                if data.get("profiles").is_none() {
                    if let Some(obj) = data.as_object_mut() {
                        obj.insert("profiles".to_string(), simd_json::json!([]));
                    }
                }
                let profiles = data
                    .get_mut("profiles")
                    .and_then(|p| p.as_array_mut())
                    .ok_or_else(|| anyhow::anyhow!("profiles field is not an array"))?;
                if !profiles.iter().any(|p| p.as_str() == Some(profile)) {
                    profiles.push(simd_json::json!(profile));
                }
                Self::incus_update_instance(name, data).await?;
                Ok(Vec::new())
            }
            ["config", "unset", name, key] => {
                let mut data = Self::incus_get_instance(name).await?;
                if let Some(config) = data.get_mut("config").and_then(|c| c.as_object_mut()) {
                    config.remove(*key);
                }
                Self::incus_update_instance(name, data).await?;
                Ok(Vec::new())
            }
            ["config", "set", name, kv] => {
                let mut data = Self::incus_get_instance(name).await?;
                if let Some((key, value)) = kv.split_once('=') {
                    if let Some(config) = data.get_mut("config").and_then(|c| c.as_object_mut()) {
                        config.insert(key.to_string(), simd_json::json!(value));
                    } else if let Some(obj) = data.as_object_mut() {
                        let mut config = HashMap::new();
                        config.insert(key.to_string(), simd_json::json!(value));
                        obj.insert("config".to_string(), simd_json::json!(config));
                    }
                }
                Self::incus_update_instance(name, data).await?;
                Ok(Vec::new())
            }
            ["config", "device", "remove", name, device] => {
                let mut data = Self::incus_get_instance(name).await?;
                if let Some(devices) = data.get_mut("devices").and_then(|d| d.as_object_mut()) {
                    devices.remove(*device);
                }
                Self::incus_update_instance(name, data).await?;
                Ok(Vec::new())
            }
            ["config", "device", "add", name, device, dev_type, rest @ ..] => {
                let mut data = Self::incus_get_instance(name).await?;
                let mut dev_config = HashMap::new();
                dev_config.insert("type".to_string(), simd_json::json!(dev_type));
                for arg in rest.iter() {
                    if let Some((k, v)) = arg.split_once('=') {
                        dev_config.insert(k.to_string(), simd_json::json!(v));
                    }
                }
                if let Some(devices) = data.get_mut("devices").and_then(|d| d.as_object_mut()) {
                    devices.insert(device.to_string(), simd_json::json!(dev_config));
                } else if let Some(obj) = data.as_object_mut() {
                    let mut devices = HashMap::new();
                    devices.insert(device.to_string(), simd_json::json!(dev_config));
                    obj.insert("devices".to_string(), simd_json::json!(devices));
                }
                Self::incus_update_instance(name, data).await?;
                Ok(Vec::new())
            }
            _ => Err(anyhow::anyhow!("Unmapped incus CLI args: {:?}", args)),
        }
    }

    /// Parse raw JSON output from `incus list --format=json` into IncusInstance structs.
    fn parse_instance_list(mut raw_json: Vec<u8>) -> Result<Vec<IncusInstance>> {
        let raw_instances: Vec<RawIncusInstance> =
            simd_json::from_slice(&mut raw_json).context("Failed to parse incus list JSON")?;

        let instances = raw_instances
            .into_iter()
            .map(|raw| {
                let storage_pool = raw
                    .devices
                    .get("root")
                    .and_then(|root| root.get("pool"))
                    .cloned();
                // Extract image description from config keys
                let image = raw
                    .config
                    .get("image.description")
                    .or_else(|| raw.config.get("volatile.base_image"))
                    .cloned();

                // Only include config if non-empty
                let config = if raw.config.is_empty() {
                    None
                } else {
                    Some(raw.config)
                };

                // Extract proxy devices as named sockets; leave rest in devices.
                let mut sockets = Vec::new();
                let mut non_proxy_devices: HashMap<String, HashMap<String, String>> =
                    HashMap::new();

                for (device_name, device_config) in raw.devices {
                    if device_config
                        .get("type")
                        .map(|t| t == "proxy")
                        .unwrap_or(false)
                    {
                        if let (Some(listen), Some(connect)) = (
                            device_config.get("listen").cloned(),
                            device_config.get("connect").cloned(),
                        ) {
                            let id = socket_id_from_connect(&connect).unwrap_or(device_name);
                            sockets.push(IncusProxySocket {
                                id,
                                listen,
                                connect,
                                bind: device_config.get("bind").cloned(),
                                uid: device_config.get("uid").cloned(),
                                gid: device_config.get("gid").cloned(),
                                mode: device_config.get("mode").cloned(),
                            });
                        }
                    } else {
                        non_proxy_devices.insert(device_name, device_config);
                    }
                }

                sockets.sort_by(|a, b| a.id.cmp(&b.id));

                let devices = if non_proxy_devices.is_empty() {
                    None
                } else {
                    Some(non_proxy_devices)
                };

                IncusInstance {
                    name: raw.name,
                    status: raw.status,
                    instance_type: raw.instance_type,
                    image,
                    storage_pool,
                    profiles: raw.profiles,
                    description: if raw.description.is_empty() {
                        None
                    } else {
                        Some(raw.description)
                    },
                    architecture: if raw.architecture.is_empty() {
                        None
                    } else {
                        Some(raw.architecture)
                    },
                    ephemeral: Some(raw.ephemeral),
                    stateful: Some(raw.stateful),
                    created_at: if raw.created_at.is_empty() {
                        None
                    } else {
                        Some(raw.created_at)
                    },
                    last_used_at: if raw.last_used_at.is_empty() {
                        None
                    } else {
                        Some(raw.last_used_at)
                    },
                    location: if raw.location.is_empty() || raw.location == "none" {
                        None
                    } else {
                        Some(raw.location)
                    },
                    project: if raw.project.is_empty() || raw.project == "default" {
                        None
                    } else {
                        Some(raw.project)
                    },
                    config,
                    devices,
                    sockets,
                }
            })
            .collect();

        Ok(instances)
    }

    /// Apply a single Create action for an instance.
    async fn apply_create(instance: &IncusInstance) -> Result<Vec<String>> {
        let mut changes = Vec::new();
        let name = &instance.name;

        // Determine the image to use; fall back to a sensible default
        let image = instance.image.as_deref().unwrap_or("images:debian/12");

        let mut create_args = vec!["init".to_string(), image.to_string(), name.to_string()];
        if let Some(pool) = instance.storage_pool.as_deref() {
            create_args.push("--storage".to_string());
            create_args.push(pool.to_string());
        }
        if instance.profiles.is_empty() {
            create_args.push("--no-profiles".to_string());
        } else {
            for profile in Self::normalize_profiles(&instance.profiles) {
                create_args.push("--profile".to_string());
                create_args.push(profile);
            }
        }
        let create_args_ref: Vec<&str> = create_args.iter().map(String::as_str).collect();
        log::info!("Creating instance '{}' from image '{}'", name, image);
        Self::run_incus_command(&create_args_ref)
            .await
            .with_context(|| format!("Failed to create instance '{}'", name))?;
        changes.push(format!("Created instance '{}'", name));

        changes.extend(Self::sync_profiles(name, None, instance).await?);
        changes.extend(Self::sync_config(name, None, instance).await?);
        changes.extend(Self::sync_devices(name, None, instance).await?);
        changes.extend(Self::sync_status(name, None, instance).await?);

        Ok(changes)
    }

    async fn apply_modify(current: &IncusInstance, desired: &IncusInstance) -> Result<Vec<String>> {
        let mut changes = Vec::new();
        changes.extend(Self::sync_profiles(&desired.name, Some(current), desired).await?);
        changes.extend(Self::sync_config(&desired.name, Some(current), desired).await?);
        changes.extend(Self::sync_devices(&desired.name, Some(current), desired).await?);
        changes.extend(Self::sync_status(&desired.name, Some(current), desired).await?);
        Ok(changes)
    }

    /// Apply a single Delete action.
    async fn apply_delete(name: &str) -> Result<Vec<String>> {
        log::info!("Force-deleting instance '{}'", name);
        Self::run_incus_command(&["delete", name, "--force"])
            .await
            .with_context(|| format!("Failed to delete instance '{}'", name))?;
        Ok(vec![format!("Deleted instance '{}'", name)])
    }

    fn is_read_only_config_key(key: &str) -> bool {
        key.starts_with("volatile.") || key.starts_with("image.")
    }

    fn normalize_profiles(profiles: &[String]) -> Vec<String> {
        let mut normalized = profiles.to_vec();
        normalized.sort();
        normalized.dedup();
        normalized
    }

    fn normalized_config(instance: &IncusInstance) -> HashMap<String, String> {
        instance
            .config
            .clone()
            .unwrap_or_default()
            .into_iter()
            .filter(|(key, _)| !Self::is_read_only_config_key(key))
            .collect()
    }

    fn managed_devices(instance: &IncusInstance) -> HashMap<String, HashMap<String, String>> {
        instance
            .devices
            .clone()
            .unwrap_or_default()
            .into_iter()
            .filter(|(name, _)| name != "root")
            .collect()
    }

    fn instances_equivalent(current: &IncusInstance, desired: &IncusInstance) -> bool {
        current.status == desired.status
            && current.instance_type == desired.instance_type
            && current.storage_pool == desired.storage_pool
            && Self::normalize_profiles(&current.profiles)
                == Self::normalize_profiles(&desired.profiles)
            && Self::normalized_config(current) == Self::normalized_config(desired)
            && Self::managed_devices(current) == Self::managed_devices(desired)
    }

    async fn sync_profiles(
        name: &str,
        current: Option<&IncusInstance>,
        desired: &IncusInstance,
    ) -> Result<Vec<String>> {
        let current_profiles = current
            .map(|instance| Self::normalize_profiles(&instance.profiles))
            .unwrap_or_default();
        let desired_profiles = Self::normalize_profiles(&desired.profiles);
        let mut changes = Vec::new();

        for profile in &current_profiles {
            if desired_profiles.contains(profile) {
                continue;
            }
            Self::run_incus_command(&["profile", "remove", name, profile])
                .await
                .with_context(|| {
                    format!("Failed to remove profile '{}' from '{}'", profile, name)
                })?;
            changes.push(format!("Removed profile '{}' from '{}'", profile, name));
        }

        for profile in &desired_profiles {
            if current_profiles.contains(profile) {
                continue;
            }
            Self::run_incus_command(&["profile", "add", name, profile])
                .await
                .with_context(|| format!("Failed to add profile '{}' to '{}'", profile, name))?;
            changes.push(format!("Added profile '{}' to '{}'", profile, name));
        }

        Ok(changes)
    }

    async fn sync_config(
        name: &str,
        current: Option<&IncusInstance>,
        desired: &IncusInstance,
    ) -> Result<Vec<String>> {
        let current_config = current.map(Self::normalized_config).unwrap_or_default();
        let desired_config = Self::normalized_config(desired);
        let mut changes = Vec::new();

        for key in current_config.keys() {
            if !desired_config.contains_key(key) {
                Self::run_incus_command(&["config", "unset", name, key])
                    .await
                    .with_context(|| format!("Failed to unset config '{}' on '{}'", key, name))?;
                changes.push(format!("Unset config '{}' on '{}'", key, name));
            }
        }

        for (key, value) in desired_config {
            if current_config.get(&key) == Some(&value) {
                continue;
            }
            let kv = format!("{}={}", key, value);
            Self::run_incus_command(&["config", "set", name, &kv])
                .await
                .with_context(|| format!("Failed to set config '{}' on '{}'", kv, name))?;
            changes.push(format!("Set config '{}' on '{}'", kv, name));
        }

        Ok(changes)
    }

    async fn sync_devices(
        name: &str,
        current: Option<&IncusInstance>,
        desired: &IncusInstance,
    ) -> Result<Vec<String>> {
        let current_devices = current.map(Self::managed_devices).unwrap_or_default();
        let desired_devices = Self::managed_devices(desired);
        let mut changes = Vec::new();

        for device_name in current_devices.keys() {
            if desired_devices.contains_key(device_name) {
                continue;
            }
            Self::run_incus_command(&["config", "device", "remove", name, device_name])
                .await
                .with_context(|| {
                    format!(
                        "Failed to remove stale device '{}' from '{}'",
                        device_name, name
                    )
                })?;
            changes.push(format!(
                "Removed stale device '{}' from '{}'",
                device_name, name
            ));
        }

        for (device_name, desired_device) in desired_devices {
            if current_devices.get(&device_name) == Some(&desired_device) {
                continue;
            }

            if current_devices.contains_key(&device_name) {
                Self::run_incus_command(&["config", "device", "remove", name, &device_name])
                    .await
                    .with_context(|| {
                        format!("Failed to remove device '{}' from '{}'", device_name, name)
                    })?;
                changes.push(format!("Removed device '{}' from '{}'", device_name, name));
            }

            let device_type = desired_device
                .get("type")
                .cloned()
                .context("Incus device definition is missing required 'type'")?;
            let mut add_args = vec![
                "config".to_string(),
                "device".to_string(),
                "add".to_string(),
                name.to_string(),
                device_name.clone(),
                device_type,
            ];
            for (key, value) in desired_device {
                if key == "type" {
                    continue;
                }
                add_args.push(format!("{}={}", key, value));
            }
            let add_args_ref: Vec<&str> = add_args.iter().map(String::as_str).collect();
            Self::run_incus_command(&add_args_ref)
                .await
                .with_context(|| format!("Failed to add device '{}' to '{}'", device_name, name))?;
            changes.push(format!("Configured device '{}' on '{}'", device_name, name));
        }

        Ok(changes)
    }

    async fn sync_status(
        name: &str,
        current: Option<&IncusInstance>,
        desired: &IncusInstance,
    ) -> Result<Vec<String>> {
        let mut changes = Vec::new();
        if current.map(|instance| instance.status.as_str()) == Some(desired.status.as_str()) {
            return Ok(changes);
        }
        match desired.status.as_str() {
            "Running" => {
                Self::run_incus_command(&["start", name])
                    .await
                    .with_context(|| format!("Failed to start instance '{}'", name))?;
                changes.push(format!("Started instance '{}'", name));
            }
            "Stopped" => {
                Self::run_incus_command(&["stop", name])
                    .await
                    .with_context(|| format!("Failed to stop instance '{}'", name))?;
                changes.push(format!("Stopped instance '{}'", name));
            }
            "Frozen" => {
                Self::run_incus_command(&["pause", name])
                    .await
                    .with_context(|| format!("Failed to freeze instance '{}'", name))?;
                changes.push(format!("Frozen instance '{}'", name));
            }
            other => anyhow::bail!(
                "Unsupported desired status '{}' for instance '{}'",
                other,
                name
            ),
        }
        Ok(changes)
    }
}

impl Default for IncusPlugin {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl StatePlugin for IncusPlugin {
    fn name(&self) -> &str {
        "incus"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<op_state_store::PluginSchema> {
        Some(incus_schema())
    }

    fn is_available(&self) -> bool {
        std::path::Path::new("/usr/bin/incus").exists()
    }

    fn unavailable_reason(&self) -> String {
        "Incus not installed (/usr/bin/incus not found)".to_string()
    }

    async fn query_current_state(&self) -> Result<Value> {
        log::info!("Querying current Incus instance state");

        let stdout = Self::run_incus_command(&["list", "--format=json"])
            .await
            .context("Failed to list Incus instances")?;

        let instances = Self::parse_instance_list(stdout)?;
        log::info!("Discovered {} Incus instance(s)", instances.len());

        let state = IncusState { instances };
        simd_json::serde::to_owned_value(state).context("Failed to serialize IncusState")
    }

    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
        let current_state: IncusState = simd_json::serde::from_owned_value(current.clone())
            .context("Failed to deserialize current IncusState")?;
        let desired_state: IncusState = simd_json::serde::from_owned_value(desired.clone())
            .context("Failed to deserialize desired IncusState")?;

        // Index current instances by name for O(1) lookups
        let current_by_name: HashMap<&str, &IncusInstance> = current_state
            .instances
            .iter()
            .map(|i| (i.name.as_str(), i))
            .collect();

        let desired_by_name: HashMap<&str, &IncusInstance> = desired_state
            .instances
            .iter()
            .map(|i| (i.name.as_str(), i))
            .collect();

        let mut actions = Vec::new();

        // Check desired instances against current state
        for desired_inst in &desired_state.instances {
            match current_by_name.get(desired_inst.name.as_str()) {
                None => {
                    // Instance does not exist yet -- needs creation
                    let config = simd_json::serde::to_owned_value(desired_inst.clone())
                        .context("Failed to serialize desired instance for Create action")?;
                    actions.push(StateAction::Create {
                        resource: desired_inst.name.clone(),
                        config,
                    });
                }
                Some(current_inst) => {
                    if !Self::instances_equivalent(current_inst, desired_inst) {
                        let changes = simd_json::serde::to_owned_value(desired_inst.clone())
                            .context("Failed to serialize desired instance for Modify action")?;
                        actions.push(StateAction::Modify {
                            resource: desired_inst.name.clone(),
                            changes,
                        });
                    }
                }
            }
        }

        // Instances in current but not in desired should be deleted
        for current_inst in &current_state.instances {
            if !desired_by_name.contains_key(current_inst.name.as_str()) {
                actions.push(StateAction::Delete {
                    resource: current_inst.name.clone(),
                });
            }
        }

        let current_hash = format!("{:x}", md5::compute(simd_json::to_string(current)?));
        let desired_hash = format!("{:x}", md5::compute(simd_json::to_string(desired)?));

        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions,
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash,
                desired_hash,
            },
        })
    }

    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        let mut changes_applied = Vec::new();
        let mut errors = Vec::new();
        let current_state = self
            .query_current_state()
            .await
            .ok()
            .and_then(|value| simd_json::serde::from_owned_value::<IncusState>(value).ok());
        let current_by_name: HashMap<String, IncusInstance> = current_state
            .map(|state| {
                state
                    .instances
                    .into_iter()
                    .map(|instance| (instance.name.clone(), instance))
                    .collect()
            })
            .unwrap_or_default();

        for action in &diff.actions {
            match action {
                StateAction::Create { resource, config } => {
                    let instance: IncusInstance =
                        simd_json::serde::from_owned_value(config.clone())
                            .context("Failed to deserialize instance config for creation")?;

                    match Self::apply_create(&instance).await {
                        Ok(changes) => changes_applied.extend(changes),
                        Err(e) => {
                            let msg = format!("Failed to create instance '{}': {}", resource, e);
                            log::error!("{}", msg);
                            errors.push(msg);
                        }
                    }
                }
                StateAction::Modify { resource, changes } => {
                    let desired: IncusInstance =
                        simd_json::serde::from_owned_value(changes.clone())
                            .context("Failed to deserialize instance config for modification")?;

                    match current_by_name.get(resource) {
                        Some(current) => match Self::apply_modify(current, &desired).await {
                            Ok(applied) => changes_applied.extend(applied),
                            Err(e) => {
                                let msg =
                                    format!("Failed to modify instance '{}': {}", resource, e);
                                log::error!("{}", msg);
                                errors.push(msg);
                            }
                        },
                        None => {
                            let msg = format!(
                                "Failed to modify instance '{}': current instance not found",
                                resource
                            );
                            log::error!("{}", msg);
                            errors.push(msg);
                        }
                    }
                }
                StateAction::Delete { resource } => match Self::apply_delete(resource).await {
                    Ok(applied) => changes_applied.extend(applied),
                    Err(e) => {
                        let msg = format!("Failed to delete instance '{}': {}", resource, e);
                        log::error!("{}", msg);
                        errors.push(msg);
                    }
                },
                StateAction::NoOp { .. } => {}
            }
        }

        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied,
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, desired: &Value) -> Result<bool> {
        log::info!("Verifying Incus state matches desired");
        let current = self.query_current_state().await?;
        let diff = self.calculate_diff(&current, desired).await?;
        let in_sync = diff.actions.is_empty();

        if in_sync {
            log::info!("Incus state is in sync with desired state");
        } else {
            log::warn!(
                "Incus state drift detected: {} action(s) needed",
                diff.actions.len()
            );
        }

        Ok(in_sync)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        log::info!("Creating Incus state checkpoint");
        let state = self.query_current_state().await?;
        let id = format!("incus-{}", chrono::Utc::now().timestamp());

        Ok(Checkpoint {
            id,
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: state,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
        log::info!("Rolling back Incus state to checkpoint '{}'", checkpoint.id);

        let current = self.query_current_state().await?;
        let diff = self
            .calculate_diff(&current, &checkpoint.state_snapshot)
            .await?;

        if diff.actions.is_empty() {
            log::info!("No rollback actions needed -- state already matches checkpoint");
            return Ok(());
        }

        let result = self.apply_state(&diff).await?;
        if result.success {
            log::info!(
                "Rollback to checkpoint '{}' completed successfully ({} change(s))",
                checkpoint.id,
                result.changes_applied.len()
            );
        } else {
            log::error!(
                "Rollback to checkpoint '{}' completed with errors: {:?}",
                checkpoint.id,
                result.errors
            );
            anyhow::bail!(
                "Rollback had {} error(s): {}",
                result.errors.len(),
                result.errors.join("; ")
            );
        }

        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: true,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_instances_equivalent_detects_config_and_device_changes() {
        let current = IncusInstance {
            name: "privacy-user-1".to_string(),
            status: "Running".to_string(),
            instance_type: "container".to_string(),
            image: Some("images:alpine/3.19".to_string()),
            storage_pool: Some("registration".to_string()),
            profiles: vec!["default".to_string()],
            config: Some(HashMap::from([(
                "user.opdbus.route_id".to_string(),
                "route-a".to_string(),
            )])),
            devices: Some(HashMap::from([(
                "privacy0".to_string(),
                HashMap::from([
                    ("type".to_string(), "nic".to_string()),
                    ("nictype".to_string(), "bridged".to_string()),
                    ("parent".to_string(), "ovsbr0".to_string()),
                ]),
            )])),
            ..Default::default()
        };
        let mut desired = current.clone();
        assert!(IncusPlugin::instances_equivalent(&current, &desired));

        desired.config = Some(HashMap::from([(
            "user.opdbus.route_id".to_string(),
            "route-b".to_string(),
        )]));
        assert!(!IncusPlugin::instances_equivalent(&current, &desired));

        desired = current.clone();
        desired.devices = Some(HashMap::from([(
            "privacy0".to_string(),
            HashMap::from([
                ("type".to_string(), "nic".to_string()),
                ("nictype".to_string(), "bridged".to_string()),
                ("parent".to_string(), "ovsbr1".to_string()),
            ]),
        )]));
        assert!(!IncusPlugin::instances_equivalent(&current, &desired));
    }
}

pub(crate) fn incus_schema() -> PluginSchema {
    let instance_fields = {
        let mut fields = HashMap::new();
        fields.insert(
            "name".to_string(),
            FieldSchema {
                field_type: FieldType::String,
                required: true,
                description: "Instance name".to_string(),
                default: None,
                example: Some(json!("privacy-user-123")),
                constraints: Vec::new(),
                read_only: true,
                read_only_when: None,
            },
        );
        fields.insert(
            "status".to_string(),
            FieldSchema {
                field_type: FieldType::Enum(vec![
                    "Running".to_string(),
                    "Stopped".to_string(),
                    "Frozen".to_string(),
                ]),
                required: true,
                description: "Instance status".to_string(),
                default: Some(json!("Stopped")),
                example: Some(json!("Running")),
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
            },
        );
        fields.insert(
            "type".to_string(),
            FieldSchema {
                field_type: FieldType::Enum(vec![
                    "container".to_string(),
                    "virtual-machine".to_string(),
                ]),
                required: true,
                description: "Instance type".to_string(),
                default: Some(json!("container")),
                example: Some(json!("container")),
                constraints: Vec::new(),
                read_only: true,
                read_only_when: None,
            },
        );
        fields.insert(
            "image".to_string(),
            FieldSchema {
                field_type: FieldType::String,
                required: false,
                description: "Source image reference".to_string(),
                default: None,
                example: Some(json!("images:debian/13")),
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
            },
        );
        fields.insert(
            "storage_pool".to_string(),
            FieldSchema {
                field_type: FieldType::String,
                required: false,
                description: "Preferred Incus storage pool for initial creation".to_string(),
                default: None,
                example: Some(json!("registration")),
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
            },
        );
        fields.insert(
            "profiles".to_string(),
            FieldSchema {
                field_type: FieldType::Array(Box::new(FieldType::String)),
                required: false,
                description: "Applied Incus profiles".to_string(),
                default: Some(json!(["default"])),
                example: Some(json!(["default"])),
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
            },
        );
        fields.insert(
            "config".to_string(),
            FieldSchema {
                field_type: FieldType::Any,
                required: false,
                description: "Instance configuration map".to_string(),
                default: Some(json!({})),
                example: Some(json!({"limits.cpu": "2"})),
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
            },
        );
        fields.insert(
            "devices".to_string(),
            FieldSchema {
                field_type: FieldType::Any,
                required: false,
                description: "Non-proxy device definitions (NICs, disks, etc.)".to_string(),
                default: Some(json!({})),
                example: Some(json!({
                    "eth0": { "type": "nic", "nictype": "bridged", "parent": "ovsbr0" }
                })),
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
            },
        );
        fields.insert(
            "description".to_string(),
            FieldSchema {
                field_type: FieldType::String,
                required: false,
                description: "Human-readable instance description".to_string(),
                default: None,
                example: Some(json!("Mail server")),
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
            },
        );
        fields.insert(
            "architecture".to_string(),
            FieldSchema {
                field_type: FieldType::String,
                required: false,
                description: "CPU architecture (e.g. x86_64)".to_string(),
                default: None,
                example: Some(json!("x86_64")),
                constraints: Vec::new(),
                read_only: true,
                read_only_when: None,
            },
        );
        fields.insert(
            "ephemeral".to_string(),
            FieldSchema {
                field_type: FieldType::Boolean,
                required: false,
                description: "Delete instance on shutdown".to_string(),
                default: Some(json!(false)),
                example: Some(json!(false)),
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
            },
        );
        fields.insert(
            "stateful".to_string(),
            FieldSchema {
                field_type: FieldType::Boolean,
                required: false,
                description: "Whether saved state exists on disk".to_string(),
                default: Some(json!(false)),
                example: Some(json!(false)),
                constraints: Vec::new(),
                read_only: true,
                read_only_when: None,
            },
        );
        fields.insert(
            "created_at".to_string(),
            FieldSchema {
                field_type: FieldType::String,
                required: false,
                description: "Creation timestamp (ISO8601)".to_string(),
                default: None,
                example: Some(json!("2024-01-01T00:00:00Z")),
                constraints: Vec::new(),
                read_only: true,
                read_only_when: None,
            },
        );
        fields.insert(
            "last_used_at".to_string(),
            FieldSchema {
                field_type: FieldType::String,
                required: false,
                description: "Last start timestamp (ISO8601)".to_string(),
                default: None,
                example: Some(json!("2024-01-01T00:00:00Z")),
                constraints: Vec::new(),
                read_only: true,
                read_only_when: None,
            },
        );
        fields.insert(
            "location".to_string(),
            FieldSchema {
                field_type: FieldType::String,
                required: false,
                description: "Cluster member name (absent on single-node)".to_string(),
                default: None,
                example: Some(json!("node-1")),
                constraints: Vec::new(),
                read_only: true,
                read_only_when: None,
            },
        );
        fields.insert(
            "project".to_string(),
            FieldSchema {
                field_type: FieldType::String,
                required: false,
                description: "Incus project name (absent when default)".to_string(),
                default: None,
                example: Some(json!("staging")),
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
            },
        );
        fields.insert(
            "sockets".to_string(),
            FieldSchema {
                field_type: FieldType::Any,
                required: false,
                description: "Proxy devices exposed as Unix sockets on the host. Each entry has an id field (device name) for named D-Bus paths.".to_string(),
                default: Some(json!([])),
                example: Some(json!([
                    {
                        "id": "grpc-socket",
                        "listen": "unix:/run/assistant.sock",
                        "connect": "tcp:127.0.0.1:50051",
                        "bind": "host",
                        "uid": "0",
                        "gid": "0",
                        "mode": "0660"
                    }
                ])),
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
            },
        );
        fields
    };

    PluginSchema::builder("incus")
        .version("1.0.0")
        .description("Incus instance management")
        .array_field(
            "instances",
            FieldType::Object(instance_fields),
            true,
            "List of Incus instances",
        )
        .example(json!({
            "instances": [
                {
                    "name": "privacy-user-123",
                    "status": "Running",
